package ai

import (
	"github.com/aarock1234/ai/pkg/model"
)

// GenerateTextResult is the outcome of GenerateText, and the aggregated
// outcome of StreamText.
type GenerateTextResult struct {
	// Content is the content of every step.
	Content []ContentPart

	// Text is the text of the final step, or the empty string when it has no
	// text.
	Text string

	// Reasoning is the reasoning of the final step.
	Reasoning []ContentPart

	// ReasoningText is the reasoning text of the final step.
	ReasoningText string

	// Files are the generated files of every step.
	Files []GeneratedFile

	// Sources are the sources of every step.
	Sources []SourceContent

	ToolCalls        []ToolCall
	StaticToolCalls  []ToolCall
	DynamicToolCalls []ToolCall

	ToolResults        []ToolResult
	StaticToolResults  []ToolResult
	DynamicToolResults []ToolResult

	// FinishReason is the finish reason of the final step.
	FinishReason    model.UnifiedFinishReason
	RawFinishReason string

	// Usage is the summed usage of every step.
	Usage LanguageModelUsage

	// TotalUsage is the same as Usage. It mirrors the upstream property.
	TotalUsage LanguageModelUsage

	// Warnings are the warnings of every step.
	Warnings []model.Warning

	// Request and Response describe the final step's model call.
	Request  StepRequest
	Response StepResponse

	// ResponseMessages are the messages generated by every step, including
	// the results of tool calls approved in the prompt. Append them to the
	// conversation to continue it.
	ResponseMessages []model.Message

	// ProviderMetadata is the final step's provider metadata.
	ProviderMetadata model.ProviderMetadata

	Steps     []StepResult
	FinalStep StepResult

	// Output is the parsed output: a string for text output and the value
	// produced by the configured Output otherwise. It is nil when no output
	// was parsed; use OutputAs for a typed value.
	Output any
}

// generateTextResultInput holds the values a result is derived from.
type generateTextResultInput struct {
	steps                   []StepResult
	initialResponseMessages []model.Message
	totalUsage              LanguageModelUsage
	output                  any
}

// newGenerateTextResult aggregates the steps of a generation. It requires at
// least one step.
func newGenerateTextResult(input generateTextResultInput) *GenerateTextResult {
	finalStep := input.steps[len(input.steps)-1]
	reasoningText, _ := finalStep.ReasoningText()

	result := &GenerateTextResult{
		Text:             finalStep.Text(),
		Reasoning:        finalStep.Reasoning(),
		ReasoningText:    reasoningText,
		FinishReason:     finalStep.FinishReason,
		RawFinishReason:  finalStep.RawFinishReason,
		Usage:            input.totalUsage,
		TotalUsage:       input.totalUsage,
		Request:          finalStep.Request,
		Response:         finalStep.Response,
		ProviderMetadata: finalStep.ProviderMetadata,
		Steps:            input.steps,
		FinalStep:        finalStep,
		Output:           input.output,
	}

	result.ResponseMessages = append(result.ResponseMessages, input.initialResponseMessages...)

	for _, step := range input.steps {
		result.Content = append(result.Content, step.Content...)
		result.Files = append(result.Files, step.Files()...)
		result.Sources = append(result.Sources, step.Sources()...)
		result.ToolCalls = append(result.ToolCalls, step.ToolCalls()...)
		result.StaticToolCalls = append(result.StaticToolCalls, step.StaticToolCalls()...)
		result.DynamicToolCalls = append(result.DynamicToolCalls, step.DynamicToolCalls()...)
		result.ToolResults = append(result.ToolResults, step.ToolResults()...)
		result.StaticToolResults = append(result.StaticToolResults, step.StaticToolResults()...)
		result.DynamicToolResults = append(result.DynamicToolResults, step.DynamicToolResults()...)
		result.Warnings = append(result.Warnings, step.Warnings...)
		result.ResponseMessages = append(result.ResponseMessages, step.Response.Messages...)
	}

	return result
}

// sumStepUsage adds the usage of every step.
func sumStepUsage(steps []StepResult) LanguageModelUsage {
	var total LanguageModelUsage

	for _, step := range steps {
		total = addLanguageModelUsage(total, step.Usage)
	}

	return total
}
